      >
        {value}K
      </div>
      {/* Bar */}
      <div
        style={{
          width: 100,
          height: 480,
          backgroundColor: "rgba(255,255,255,0.06)",
          borderRadius: 12,
          display: "flex",
          flexDirection: "column",
          justifyContent: "flex-end",
          overflow: "hidden",
          border: highlight ? `2px solid ${color}66` : "none",
          position: "relative",
        }}
      >
        <div
          style={{
            width: "100%",
            height: barHeight,
            background: highlight
              ? `linear-gradient(180deg, ${color}, ${color}88)`
              : `linear-gradient(180deg, ${color}88, ${color}44)`,
            borderRadius: 10,
            position: "relative",
          }}
        />
        {highlight && (
          <div
            style={{
              position: "absolute",
