          />
        )}
      </div>
      {/* Month */}
      <div
        style={{
          fontSize: 36,
          fontWeight: 700,
          color: highlight ? COLORS.lightPink : COLORS.mutedPurple,
          opacity: p,
        }}
      >
        {month}
      </div>
      {highlight && (
        <div
          style={{
            fontSize: 28,
            fontWeight: 700,
            color: color,
            opacity: p,
            backgroundColor: `${color}22`,
            border: `1px solid ${color}44`,
            borderRadius: 10,
            padding: "6px 18px",
          }}
        >
          🚀 Trending
        </div>
      )}
    </div>
  );
};

